  "Repair cafe or shop": {"nl": "Repaircafé of reparatiezaak", "de": "Repair-Café oder Werkstatt", "fr": "Repair Café ou atelier", "zh": "维修咖啡馆或维修店"},
  "Appointment": {"nl": "Afspraak", "de": "Termin", "fr": "Rendez-vous", "zh": "预约时间"},
  "Move to:": {"nl": "Volgende stap:", "de": "Weiter zu:", "fr": "Passer à :", "zh": "推进至："},
  "Add appointment to calendar": {"nl": "Afspraak in agenda", "de": "Termin zum Kalender", "fr": "Ajouter le rendez-vous", "zh": "预约加入日历"},
