  "How did it go?": {"nl": "Hoe ging het?", "de": "Wie ist es gelaufen?", "fr": "Comment ça s’est passé ?", "zh": "修得怎么样？"},
  "Keep the good going": {"nl": "Blijf goed bezig", "de": "Weiter Gutes bewirken", "fr": "Faites durer le positif", "zh": "让好东西继续用下去"},
  "My repairs.": {"nl": "Mijn reparaties.", "de": "Meine Reparaturen.", "fr": "Mes réparations.", "zh": "我的维修。"},
  "Track repairs in progress and keep the ones you finished. Saved in this browser, on this device.": {"nl": "Volg lopende reparaties en bewaar afgeronde. Opgeslagen in deze browser, op dit apparaat.", "de": "Laufende Reparaturen verfolgen und abgeschlossene behalten. Gespeichert in diesem Browser auf diesem Gerät.", "fr": "Suivez les réparations en cours et gardez les terminées. Enregistrées dans ce navigateur, sur cet appareil.", "zh": "追踪进行中的维修，保留已完成记录。数据保存在本机的当前浏览器。"},
  "items fixed": {"nl": "apparaten gerepareerd", "de": "Geräte repariert", "fr": "objets réparés", "zh": "件已修好"},
  "estimated avoided": {"nl": "geschat vermeden", "de": "geschätzt vermieden", "fr": "évité estimé", "zh": "估算减少"},
  "Only “Fixed” outcomes count. Savings use full-success category estimates and 0.5 displacement, not measured reductions.": {"nl": "Alleen “Gerepareerd” telt. Besparingen gebruiken categorieschattingen bij succes en 0.5 vervanging, geen gemeten dalingen.", "de": "Nur „Repariert“ zählt. Einsparungen nutzen Kategorieschätzungen bei vollem Erfolg und 0.5 Verdrängung, keine gemessenen Reduktionen.", "fr": "Seuls les résultats « Réparé » comptent. Les économies utilisent les estimations de réussite par catégorie et 0.5 de substitution, pas des réductions mesurées.", "zh": "仅计入“已修好”结果。收益使用完全修好的类别估算及 0.5 替代系数，并非实测减排。"},
  "{count} fixed item(s) have no factor and are excluded from impact totals.": {"nl": "Voor {count} gerepareerde apparaten ontbreekt een factor; ze tellen niet mee in de milieutotalen.", "de": "Für {count} reparierte Geräte fehlt ein Faktor; sie sind in den Umweltsummen nicht enthalten.", "fr": "{count} objets réparés n’ont pas de facteur et sont exclus des totaux d’impact.", "zh": "{count} 件已修好物品缺少系数，未计入环保合计。"},
  "In progress": {"nl": "In behandeling", "de": "In Arbeit", "fr": "En cours", "zh": "进行中"},
  "Track my {item} repair": {"nl": "Volg mijn reparatie van {item}", "de": "Reparatur von {item} verfolgen", "fr": "Suivre la réparation : {item}", "zh": "追踪我的{item}维修"},
  "Track this repair from booking to done. Add the appointment to your calendar and keep the warranty date.": {"nl": "Volg deze reparatie van afspraak tot klaar. Zet de afspraak in je agenda en bewaar de garantiedatum.", "de": "Verfolge diese Reparatur vom Buchen bis zum Abschluss. Termin zum Kalender hinzufügen und Garantiedatum aufbewahren.", "fr": "Suivez cette réparation du rendez-vous à la fin. Ajoutez le rendez-vous au calendrier et gardez la date de garantie.", "zh": "从预约到完成，追踪此次维修。可将预约加入日历，并保存保修日期。"},
  "Check an item to start tracking a repair →": {"nl": "Check een apparaat om een reparatie te volgen →", "de": "Gerät prüfen und Reparatur verfolgen →", "fr": "Vérifiez un objet pour suivre sa réparation →", "zh": "先检测物品，再开始追踪维修 →"},
  "Already done? Log your {value1} repair": {"nl": "Al klaar? Leg je reparatie van {value1} vast", "de": "Schon fertig? Reparatur von {value1} erfassen", "fr": "Déjà terminé ? Notez la réparation de {value1}", "zh": "已经修完？记录{value1}的维修"},
  "Outcome added to this log.": {"nl": "Uitkomst toegevoegd.", "de": "Ergebnis zum Log hinzugefügt.", "fr": "Résultat ajouté au journal.", "zh": "结果已加入日志。"},
  "Export CSV to keep a copy.": {"nl": "Exporteer CSV om een kopie te bewaren.", "de": "CSV exportieren, um eine Kopie zu behalten.", "fr": "Exportez un CSV pour garder une copie.", "zh": "导出 CSV 留存副本。"},
  "It is saved in this browser.": {"nl": "Opgeslagen in deze browser.", "de": "In diesem Browser gespeichert.", "fr": "Enregistré dans ce navigateur.", "zh": "已保存在当前浏览器。"},
