  "Link ready. Copy it from the field below.": {"nl": "Link klaar. Kopieer hem hieronder.", "de": "Link bereit. Aus dem Feld unten kopieren.", "fr": "Lien prêt. Copiez-le dans le champ ci-dessous.", "zh": "链接已就绪，可从下方输入框复制。"},
  "Link copied.": {"nl": "Link gekopieerd.", "de": "Link kopiert.", "fr": "Lien copié.", "zh": "链接已复制。"},
  "Copy was not available. Select and copy the link below.": {"nl": "Kopiëren niet beschikbaar. Selecteer en kopieer de link hieronder.", "de": "Kopieren nicht verfügbar. Link unten markieren und kopieren.", "fr": "Copie indisponible. Sélectionnez et copiez le lien ci-dessous.", "zh": "无法自动复制，请选中并复制下方链接。"},
