export function initialLang(): Lang {
  try { const saved = localStorage.getItem('fixodds-lang'); if (langs.some(l => l.code === saved)) return saved as Lang; } catch { /* optional preference */ }
  const browser = typeof navigator === 'undefined' ? '' : navigator.language.toLowerCase();
  return langs.find(l => l.code !== 'en' && browser.startsWith(l.code))?.code || 'en';
}
let active = initialLang();
const listeners = new Set<() => void>();
export function setLanguage(lang: Lang) {
  active = lang;
  if (typeof document !== 'undefined') document.documentElement.lang = lang;
  try { localStorage.setItem('fixodds-lang', lang); } catch { /* optional preference */ }
  listeners.forEach(listener => listener());
}
export const locale = () => ({ en: 'en-GB', nl: 'nl-NL', de: 'de-DE', fr: 'fr-FR', zh: 'zh-CN' })[active];
export function t(text: string, vars: Record<string, string | number> = {}): string {
  const translated = active === 'en' ? text : dictionary[text]?.[active] || text;
  return translated.replace(/\{(\w+)\}/g, (placeholder, name: string) => Object.hasOwn(vars, name) ? String(vars[name]) : placeholder);
}
const LangContext = createContext({ lang: active, setLang: setLanguage });
const subscribe = (listener: () => void) => { listeners.add(listener); return () => { listeners.delete(listener); }; };
export function LangProvider({ children }: { children: ReactNode }) {
  const lang = useSyncExternalStore(subscribe, () => active, () => 'en' as Lang);
  useEffect(() => { document.documentElement.lang = lang; }, [lang]);
  return createElement(LangContext.Provider, { value: { lang, setLang: setLanguage } }, children);
}
export const useLang = () => useContext(LangContext);
